query($owner: String!, $name: String!) {
  repository(owner: $owner, name: $name) {
p0: pullRequest(number: 47) { ...pr }
p1: pullRequest(number: 48) { ...pr }
p2: pullRequest(number: 49) { ...pr }
p3: pullRequest(number: 999999) { ...pr }
  }
}
fragment checks on StatusCheckRollup {
  contexts(first: 100) {
    nodes {
      __typename
      ... on CheckRun { name status conclusion detailsUrl }
      ... on StatusContext { context state targetUrl }
    }
  }
}
fragment pr on PullRequest {
  number state isDraft title body headRefOid baseRefName mergeable mergeStateStatus reviewDecision
  additions deletions changedFiles
  mergeCommit { oid }
  author { login ... on User { databaseId } ... on Bot { databaseId } }
  labels(first: 100) { nodes { name } }
  statusCheckRollup { ...checks }
}

